import{_ as t,o as e,c as s,a2 as o}from"./chunks/framework.CIOzaBgM.js";const n="/ragflow-book/assets/v05-chat-metafilter.CubeoRRJ.png",k=JSON.parse('{"title":"第 19 章 元数据过滤与标签","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/19-metadata-filter.md","filePath":"chapters/19-metadata-filter.md","lastUpdated":1791471399000}'),i={name:"chapters/19-metadata-filter.md"};function l(p,a,d,c,r,u){return e(),s("div",null,[...a[0]||(a[0]=[o(`<h1 id="第-19-章-元数据过滤与标签" tabindex="-1">第 19 章 元数据过滤与标签 <a class="header-anchor" href="#第-19-章-元数据过滤与标签" aria-label="Permalink to &quot;第 19 章 元数据过滤与标签&quot;">​</a></h1><blockquote><p>本章目标：让检索先按&quot;文档属性&quot;缩小范围，再在范围内找内容。涉及元数据的存储、过滤条件的运算符、让 LLM 从问题里推出过滤条件，以及 RAGFlow 的&quot;标签&quot;排序特征。 前置：第 13、18 章。对应代码：<code>v0.5</code> 的 <code>backend/internal/metadata/</code>（<code>v1.0</code> 有一处修复）。</p></blockquote><h2 id="_19-1-问题-型号混淆" tabindex="-1">19.1 问题：型号混淆 <a class="header-anchor" href="#_19-1-问题-型号混淆" aria-label="Permalink to &quot;19.1 问题：型号混淆&quot;">​</a></h2><p>第 1 章的例子：S1 和 S2 两份手册的结构几乎一样，问&quot;S1 的保修期多久&quot;，检索把两份手册的保修段落一起送进了提示词，模型就把 S2 的&quot;研磨器保修 5 年&quot;安到了 S1 头上。</p><p>相似度解决不了这个问题：&quot;S1 的保修&quot;和&quot;S2 的保修&quot;在语义上本来就很近。需要的是一个<strong>硬条件</strong>：只在&quot;产品型号 = S1&quot;的文档里检索。</p><h2 id="_19-2-ragflow-的做法" tabindex="-1">19.2 RAGFlow 的做法 <a class="header-anchor" href="#_19-2-ragflow-的做法" aria-label="Permalink to &quot;19.2 RAGFlow 的做法&quot;">​</a></h2><h3 id="元数据存在哪" tabindex="-1">元数据存在哪 <a class="header-anchor" href="#元数据存在哪" aria-label="Permalink to &quot;元数据存在哪&quot;">​</a></h3><p>每个文档的元数据是一个键值字典，存在检索引擎里一个单独的&quot;文档元数据&quot;索引中（<code>DocEngine</code> 接口里的 <code>CreateMetadataStore / InsertMetadata / SearchMetadata</code>，<code>engine.go:52</code> 起）。来源有两个：Extractor 自动抽取（第 18 章），或者用户在界面上手动编辑。</p><h3 id="三种过滤模式" tabindex="-1">三种过滤模式 <a class="header-anchor" href="#三种过滤模式" aria-label="Permalink to &quot;三种过滤模式&quot;">​</a></h3><p><code>ApplyMetaDataFilter</code>（<code>internal/service/metadata_filter.go</code>）的注释：</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ApplyMetaDataFilter applies metadata filtering rules and returns filtered doc_ids</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Supports three modes:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// - auto: generate filter conditions via LLM</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// - semi_auto: generate conditions using selected metadata keys only via LLM</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// - manual: directly filter based on provided conditions</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// When kbIDs is supplied, metadata filters are pushed down to the doc metadata</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// index (ES/Infinity) via FilterDocIdsByMetaPushdown instead of being evaluated</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// in-memory. The in-memory meta_filter path remains the fallback.</span></span></code></pre></div><ul><li><strong>manual</strong>：聊天助手上配置固定的条件，比如这个助手只回答 S1 的问题；</li><li><strong>auto</strong>：让 LLM 读问题和元数据，自己生成条件；</li><li><strong>semi_auto</strong>：同样由 LLM 生成，但只允许使用指定的几个键。</li></ul><p>条件能下推到检索引擎时就下推，否则在内存里求值。</p><h3 id="llm-怎么生成条件" tabindex="-1">LLM 怎么生成条件 <a class="header-anchor" href="#llm-怎么生成条件" aria-label="Permalink to &quot;LLM 怎么生成条件&quot;">​</a></h3><p>提示词是 <code>rag/prompts/meta_filter.md</code>，Go 运行时从这个文件读取（<code>metadata_filter.go:96</code> 的 <code>getMetaFilterTemplate</code>）。它把元数据组织成&quot;键 → 值 → 文档 id 列表&quot;给模型看：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. **Metadata Structure**:</span></span>
<span class="line"><span>   - Metadata is provided as JSON where keys are attribute names (e.g., &quot;color&quot;), and values are objects mapping attribute values to document IDs.</span></span>
<span class="line"><span>   - Example:</span></span>
<span class="line"><span>     {</span></span>
<span class="line"><span>       &quot;color&quot;: {&quot;red&quot;: [&quot;doc1&quot;], &quot;blue&quot;: [&quot;doc2&quot;]},</span></span>
<span class="line"><span>       &quot;listing_date&quot;: {&quot;2025-07-11&quot;: [&quot;doc1&quot;], &quot;2025-08-01&quot;: [&quot;doc2&quot;]}</span></span>
<span class="line"><span>     }</span></span></code></pre></div><p>可用的运算符有 14 个：<code>contains</code>、<code>not contains</code>、<code>in</code>、<code>not in</code>、<code>start with</code>、<code>end with</code>、<code>empty</code>、<code>not empty</code>、<code>=</code>、<code>≠</code>、<code>&gt;</code>、<code>&lt;</code>、<code>≥</code>、<code>≤</code>。提示词里还写了几条推理规则，比如&quot;七月份&quot;要转成 <code>≥ 2025-07-01 且 &lt; 2025-08-01</code> 两个条件、&quot;不要蓝色的&quot;要用 <code>≠</code>。输出是 <code>{&quot;logic&quot;: &quot;and&quot;|&quot;or&quot;, &quot;conditions&quot;: [...]}</code>。</p><p>模板最后一段是当前任务，元数据和问题都放在这里，user 消息只有一句 <code>&quot;Generate filters:&quot;</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>**Current Task**:</span></span>
<span class="line"><span>- Today&#39;s date: {{ current_date }}</span></span>
<span class="line"><span>- Available metadata keys: {{ metadata_keys }}</span></span>
<span class="line"><span>- User query: &quot;{{ user_question }}&quot;</span></span></code></pre></div><h3 id="一条都没匹配上" tabindex="-1">一条都没匹配上 <a class="header-anchor" href="#一条都没匹配上" aria-label="Permalink to &quot;一条都没匹配上&quot;">​</a></h3><p>如果过滤条件一份文档都没匹配上，不能把 <code>doc_ids</code> 设成空列表，因为空列表在检索里的意思是&quot;不限制&quot;。RAGFlow 用一个哨兵值（<code>NoMatchDocIDSentinel = &quot;-999&quot;</code>，<code>metadata_filter.go:91</code>）：检索范围限定在一个不存在的文档上，结果自然就是空的。</p><h3 id="标签-另一种-属性" tabindex="-1">标签：另一种&quot;属性&quot; <a class="header-anchor" href="#标签-另一种-属性" aria-label="Permalink to &quot;标签：另一种&quot;属性&quot;&quot;">​</a></h3><p>元数据是<strong>硬过滤</strong>；RAGFlow 还有一种<strong>软加权</strong>，叫标签（tag）。数据集可以配置一份&quot;标签文件&quot;：一些示例文本和它们对应的标签。</p><ul><li>入库时，Extractor 按这份文件给每个 chunk 打上带权重的标签，写进 <code>tag_feas</code> 字段（ES 里的 <code>rank_features</code> 类型）；</li><li>检索时，<code>LabelQuestion</code>（<code>internal/service/tag.go:99</code>）用同一份文件给<strong>问题</strong>打标签，得到一组标签权重，作为 <code>RankFeature</code> 传给检索；</li><li>第二阶段打分时，<code>applyRankFeatureScores</code> 计算问题标签和 chunk 标签的余弦，乘以 10 加到 <code>sim</code> 上（第 13 章 13.4 节）。</li></ul><p>标签不会把任何东西排除出去，只是让&quot;同一类&quot;的 chunk 往前排。mini-ragflow 没有实现标签，这一节只读源码。</p><h2 id="_19-3-从零实现" tabindex="-1">19.3 从零实现 <a class="header-anchor" href="#_19-3-从零实现" aria-label="Permalink to &quot;19.3 从零实现&quot;">​</a></h2><h3 id="存储" tabindex="-1">存储 <a class="header-anchor" href="#存储" aria-label="Permalink to &quot;存储&quot;">​</a></h3><p>文档表加了一列 <code>meta_fields</code>（JSON），store 启动时自动补列。<code>store.ListDocMeta(kbIDs)</code> 一次读出所有文档的元数据，在内存里求值。mini-ragflow 的数据集规模不大，没有做下推。</p><h3 id="条件求值" tabindex="-1">条件求值 <a class="header-anchor" href="#条件求值" aria-label="Permalink to &quot;条件求值&quot;">​</a></h3><p><code>metadata.Match</code>（<code>backend/internal/metadata/metadata.go</code>）实现了上面的 14 个运算符。一个实用的细节：<strong>能解析成数字就按数字比较，否则按字符串比较</strong>。ISO 格式的日期（<code>2026-07-15</code>）按字符串比较时顺序恰好是对的，所以日期也不需要特殊处理：</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cmp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> func</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	a, errA </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> strconv.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ParseFloat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(val, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	b, errB </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> strconv.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ParseFloat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(want, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> errA </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nil</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> errB </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> strings.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Compare</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(val, want)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>文档根本没有这个键时，<code>≠</code>、<code>not contains</code>、<code>not in</code> 算满足，其余的都算不满足。&quot;不是蓝色的&quot;当然包括没有标颜色的。</p><h3 id="三处接入" tabindex="-1">三处接入 <a class="header-anchor" href="#三处接入" aria-label="Permalink to &quot;三处接入&quot;">​</a></h3><ol><li><strong>检索接口</strong>：<code>POST /api/v1/retrieval</code> 增加 <code>metadata_condition</code> 参数，先算出允许的文档 id，再和请求里的 <code>document_ids</code> 取交集，一份都不剩就用哨兵 <code>&quot;-999&quot;</code>；</li><li><strong>聊天助手</strong>：<code>meta_data_filter: {method: &quot;auto&quot;|&quot;manual&quot;, manual: [...]}</code>，在检索之前生成或应用条件，执行轨迹里会记一行 <code>metadata filter … → N documents</code>；</li><li><strong>元数据汇总</strong>：<code>GET /api/v1/datasets/{id}/metadata/summary</code> 返回&quot;键 → 值 → 文档 id&quot;，既给 LLM 当输入，也给检索测试页做下拉选项。</li></ol><p><code>metadata.Generate</code> 用的是 RAGFlow 的 <code>meta_filter.md</code> 原文（通过 <code>go:embed</code> 嵌入，Apache-2.0）。生成出来的条件里，<strong>不存在的键会被丢掉</strong>，这是一道防止模型乱编的保险。</p><h3 id="踩坑记录-1-精简过的提示词-小模型不买账" tabindex="-1">踩坑记录 1：精简过的提示词，小模型不买账 <a class="header-anchor" href="#踩坑记录-1-精简过的提示词-小模型不买账" aria-label="Permalink to &quot;踩坑记录 1：精简过的提示词，小模型不买账&quot;">​</a></h3><p>最初为了省 token，<code>Generate</code> 用的是一个自己精简过的提示词。用 qwen2.5:3b 测试&quot;S2 怎么除垢？&quot;，它一个条件都没生成。于是换成 RAGFlow 的原版提示词（带详细示例）。复制过来以后 mock 测试却失败了：mock 模型在提示词里找不到 <code>- User query: &quot;…&quot;\\n</code> 这一行。原因是 RAGFlow 的这个文件是 <strong>CRLF 换行</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ file rag/prompts/meta_filter.md</span></span>
<span class="line"><span>rag/prompts/meta_filter.md: Unicode text, UTF-8 text, with CRLF line terminators</span></span></code></pre></div><p>另外，提示词的示例里也有 <code>- User query:</code> 字样，mock 要找的是最后一个（<code>LastIndex</code>），而不是第一个。</p><h3 id="踩坑记录-2-git-又把-crlf-换了回来" tabindex="-1">踩坑记录 2：git 又把 CRLF 换了回来 <a class="header-anchor" href="#踩坑记录-2-git-又把-crlf-换了回来" aria-label="Permalink to &quot;踩坑记录 2：git 又把 CRLF 换了回来&quot;">​</a></h3><p>写这一章时，作者在一个新的 worktree 里检出 v0.5 重跑测试，结果两个测试失败了：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--- PASS: TestOperators (0.00s)</span></span>
<span class="line"><span>--- FAIL: TestGenerateWithMock (0.00s)</span></span>
<span class="line"><span>--- FAIL: TestMetadataExtractionAndFilters (0.04s)</span></span></code></pre></div><p>仓库里存的明明是 LF，检出后却又变成了 CRLF：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git config --get core.autocrlf</span></span>
<span class="line"><span>true</span></span>
<span class="line"><span>$ file backend/internal/metadata/meta_filter.md     # 新 worktree 里</span></span>
<span class="line"><span>backend/internal/metadata/meta_filter.md: Unicode text, UTF-8 text, with CRLF line terminators</span></span></code></pre></div><p>作者的全局 git 配置是 <code>core.autocrlf=true</code>，检出时会把 LF 转成 CRLF。v1.0 的修法是&quot;不信任文件的换行符&quot;：加载提示词时先统一成 LF，同时加了 <code>.gitattributes</code>（<code>* text=auto eol=lf</code>）。修复后，在同一个 CRLF 的 worktree 里测试通过：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--- PASS: TestOperators (0.00s)</span></span>
<span class="line"><span>--- PASS: TestGenerateWithMock (0.00s)</span></span>
<span class="line"><span>ok  	mini-ragflow/internal/metadata	0.002s</span></span>
<span class="line"><span>--- PASS: TestMetadataExtractionAndFilters (0.07s)</span></span>
<span class="line"><span>ok  	mini-ragflow/internal/api	0.076s</span></span></code></pre></div><p>所以，如果你的 git 也开启了 <code>autocrlf</code>，<code>v0.5</code> 这个标签上会有两个测试失败，请使用 <code>v1.0</code>，或者先执行 <code>git config core.autocrlf false</code> 再检出。</p><h3 id="真实模型下的结果" tabindex="-1">真实模型下的结果 <a class="header-anchor" href="#真实模型下的结果" aria-label="Permalink to &quot;真实模型下的结果&quot;">​</a></h3><p>mock 模型能准确生成条件（它只是在问题里查找元数据的值）。真实的 qwen2.5:3b 用原版提示词，表现是这样的（真实输出节选，第一段省略了前面的长篇解释，第二段压缩了 JSON 里的空白）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>S2 怎么除垢？ → &#39;...the available metadata does not provide any information that directly relates to the query...</span></span>
<span class="line"><span>\`\`\`json</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;logic&quot;: &quot;and&quot;,</span></span>
<span class="line"><span>  &quot;conditions&quot;: []</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>\`\`\`&#39;</span></span>
<span class="line"><span>S1 的保修期多久？ → &#39;\`\`\`json</span></span>
<span class="line"><span>{ &quot;logic&quot;: &quot;and&quot;, &quot;conditions&quot;: [</span></span>
<span class="line"><span>    {&quot;key&quot;: &quot;empty&quot;, &quot;value&quot;: &quot;&quot;, &quot;op&quot;: &quot;not empty&quot;},</span></span>
<span class="line"><span>    {&quot;key&quot;: &quot;product_model&quot;, &quot;value&quot;: &quot;S1&quot;, &quot;op&quot;: &quot;=&quot;},</span></span>
<span class="line"><span>    {&quot;key&quot;: &quot;warranty_period&quot;, &quot;value&quot;: &quot;&quot;, &quot;op&quot;: &quot;not empty&quot;} ] }</span></span>
<span class="line"><span>\`\`\`&#39;</span></span></code></pre></div><p>第一个问题它认为&quot;元数据和问题无关&quot;；第二个问题它把键名&quot;产品型号&quot;<strong>翻译</strong>成了 <code>product_model</code>，还凭空编了两个键。后者被&quot;丢弃不存在的键&quot;这道保险全部拦了下来，结果是一个条件都没生成。<strong>auto 模式需要更强的模型</strong>。同样的模型配合 manual 模式（固定条件 <code>产品型号 = S1</code>）则工作正常：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A: 根据知识库中的信息，整机保修期为2年，加热组件保修期为3年。……[ID:0]</span></span>
<span class="line"><span>   [&#39;metadata filter {&quot;logic&quot;:&quot;&quot;,&quot;conditions&quot;:[{&quot;key&quot;:&quot;产品型号&quot;,&quot;op&quot;:&quot;=&quot;,&quot;value&quot;:&quot;S1&quot;}]} → 1 documents&#39;]</span></span></code></pre></div><p>这一次回答里没有再混入 S2 的&quot;研磨器保修 5 年&quot;。</p><h2 id="_19-4-运行与验证" tabindex="-1">19.4 运行与验证 <a class="header-anchor" href="#_19-4-运行与验证" aria-label="Permalink to &quot;19.4 运行与验证&quot;">​</a></h2><p>用 mock 模型完整地走一遍（UI 脚本 <code>e2e/ui-v05.mjs</code> 的第二部分，真实输出）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q: S2 怎么除垢？</span></span>
<span class="line"><span>A: 根据知识库：当屏幕提示&quot;请除垢&quot;时（通常每 500 杯或每 3 个月），按以下步骤除垢： 1。1. 将 1 包 S2 专用除垢粉溶于 1.5 升温水，倒入水箱 1。</span></span>
<span class="line"><span>   本轮执行轨迹 | metadata filter {&quot;logic&quot;:&quot;and&quot;,&quot;conditions&quot;:[{&quot;key&quot;:&quot;产品型号&quot;,&quot;op&quot;:&quot;=&quot;,&quot;value&quot;:&quot;S2&quot;}]} → 1 documents | retrieved 5 of 5 chunks …</span></span></code></pre></div><p><img src="`+n+'" alt="图 19-1：开启 auto 元数据过滤的聊天助手。"></p><p><em>图 19-1：开启了 auto 元数据过滤的聊天助手（mock 模型）。</em></p><h2 id="_19-5-练习" tabindex="-1">19.5 练习 <a class="header-anchor" href="#_19-5-练习" aria-label="Permalink to &quot;19.5 练习&quot;">​</a></h2><ol><li><strong>巩固</strong>：给《员工休假制度》加一个元数据 <code>生效日期: 2026-01-01</code>，用检索测试页的元数据过滤试试 <code>生效日期 ≥ 2026-01-01</code> 和 <code>&lt; 2026-01-01</code>。</li><li><strong>扩展</strong>：实现 RAGFlow 的 <code>semi_auto</code> 模式：只把用户指定的键交给 LLM。想一想，它能不能缓解 qwen2.5:3b 乱翻译键名的问题？</li><li><strong>读源码</strong>：读 <code>internal/ingestion/component/tag_query.go</code>（<code>LabelQuestion</code> 调用的 <code>LoadTagQueryIndex</code> / <code>MatchTagQuery</code> 在这里），弄清楚&quot;给问题打标签&quot;用的是什么算法：向量？关键词？</li></ol><h2 id="_19-6-延伸阅读" tabindex="-1">19.6 延伸阅读 <a class="header-anchor" href="#_19-6-延伸阅读" aria-label="Permalink to &quot;19.6 延伸阅读&quot;">​</a></h2><ul><li><code>internal/service/metadata_filter.go</code>、<code>internal/service/tag.go</code></li><li><code>rag/prompts/meta_filter.md</code></li><li>Elasticsearch 文档：<code>rank_features</code> 字段与 <code>rank_feature</code> 查询</li></ul>',62)])])}const q=t(i,[["render",l]]);export{k as __pageData,q as default};
